$ErrorActionPreference='Stop';$o=[ordered]@{Found=$false;Installed=$false;DownloadResult=-1;ResultCode=-1;HResult=0;RebootRequired=$false;Title='';Error=''};try{$s=New-Object -ComObject Microsoft.Update.Session;$q=$s.CreateUpdateSearcher();$r=$q.Search('IsInstalled=0 and UpdateID=''__UPDATE_ID__''');if($r.Updates.Count -gt 0){$u=$r.Updates.Item(0);$o.Found=$true;$o.Title=[string]$u.Title;if(-not $u.EulaAccepted){$u.AcceptEula()};$c=New-Object -ComObject Microsoft.Update.UpdateColl;[void]$c.Add($u);if(-not $u.IsDownloaded){$d=$s.CreateUpdateDownloader();$d.Updates=$c;$dr=$d.Download();$o.DownloadResult=[int]$dr.ResultCode};if($u.IsDownloaded){$i=$s.CreateUpdateInstaller();$i.Updates=$c;$ir=$i.Install();$o.ResultCode=[int]$ir.ResultCode;$o.HResult=[int]$ir.HResult;$o.RebootRequired=[bool]$ir.RebootRequired;$o.Installed=($o.ResultCode -eq 2 -or $o.ResultCode -eq 3)}}}catch{$o.Error=[string]$_.Exception.Message};[pscustomobject]$o | ConvertTo-Json -Compress